    { id: 26, name: 'Mosaic Style', component: Page26 },
    { id: 27, name: 'Full Width Sections', component: Page27 },
    { id: 28, name: 'Quote Focus', component: Page28 },
    { id: 29, name: 'Tech Style', component: Page29 },
    { id: 30, name: 'Playful', component: Page30 }
  ];

  // Single page view
  if (!showAllPages) {
    const selectedPage = pages.find(p => p.id === pageStyle) || pages[0];
    const PageComponent = selectedPage.component;
    return (
      <div ref={containerRef} className="about-us-pages" style={{ fontFamily }}>
        <link href="https://fonts.googleapis.com/css2?family=Noto+Sans+Hebrew:wght@200;300;400;500;600;700;800;900&display=swap" rel="stylesheet" />
        <PageComponent />
