  // All pages showcase
  return (
    <div ref={containerRef} className="about-us-pages" style={{ backgroundColor: '#E4E4E7', padding: '40px', fontFamily }}>
      <link href="https://fonts.googleapis.com/css2?family=Noto+Sans+Hebrew:wght@200;300;400;500;600;700;800;900&display=swap" rel="stylesheet" />

      {/* Title */}
      <div style={{ textAlign: 'center', marginBottom: '48px' }}>
        <h1 style={{ fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif', fontSize: '36px', fontWeight: '700', color: '#18181B', margin: '0 0 8px' }}>30 About Us Page Designs</h1>
        <p style={{ fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif', fontSize: '16px', color: '#71717A' }}>Full page layouts with Noto Sans Hebrew</p>
