          return (
            <div key={page.id} style={{
              backgroundColor: '#FFFFFF',
              borderRadius: '20px',
              overflow: 'hidden',
              boxShadow: '0 4px 20px rgba(0,0,0,0.08)',
              opacity: prefersReducedMotion ? 1 : (isInView ? 1 : 0),
              transform: prefersReducedMotion ? 'none' : (isInView ? 'translateY(0)' : 'translateY(20px)'),
              transition: prefersReducedMotion ? 'none' : `opacity 400ms ease-out ${entranceDelay}ms, transform 400ms ease-out ${entranceDelay}ms`
            }}>
              {/* Page Label */}
              <div style={{ padding: '16px 24px', borderBottom: '1px solid #E4E4E7', display: 'flex', alignItems: 'center', gap: '16px', backgroundColor: '#FAFAFA' }}>
                <span style={{ fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif', fontSize: '14px', fontWeight: '700', color: '#FFFFFF', backgroundColor: accentColor, padding: '6px 14px', borderRadius: '6px' }}>{page.id}</span>
                <span style={{ fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif', fontSize: '16px', fontWeight: '600', color: '#3F3F46' }}>{page.name}</span>
              </div>

              {/* Page Content */}
              <div style={{ maxHeight: '800px', overflow: 'hidden' }}>
                <PageComponent />
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

