          <div
            style={{
              width: '100%',
              paddingBottom: '120%',
              position: 'relative',
              overflow: 'hidden',
              borderRadius: '0px'
            }}
          >
            <img
              src={aboutImage}
              alt="About"
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                height: '100%',
                objectFit: 'cover'
              }}
            />
          </div>
        </div>

        {/* Content Side */}
        <div
          className="dual-content"
          style={{
            width: '50%',
            order: isImageLeft ? 2 : 1,
            opacity: shouldAnimate ? (isVisible ? 1 : 0) : 1,
            transform: shouldAnimate ? (isVisible ? 'translateX(0)' : `translateX(${isImageLeft ? '40px' : '-40px'})`) : 'translateX(0)',
            transition: shouldAnimate ? `opacity ${animationDuration}ms ease-out ${animationDuration * 0.15}ms, transform ${animationDuration}ms ease-out ${animationDuration * 0.15}ms` : 'none'
          }}
        >
          {/* Title */}
          <h2
            style={{
              fontSize: `clamp(${titleFontSize * 0.6}px, ${titleFontSize * 0.08}vw + ${titleFontSize * 0.4}px, ${titleFontSize}px)`,
              fontWeight: '600',
              color: titleColor,
              margin: '0 0 32px 0',
              lineHeight: '1.2',
              fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
            }}
          >
            {sectionTitle}
          </h2>

          {/* Body Text */}
          <div style={{ marginBottom: showStats ? '48px' : '0' }}>
            {paragraphs.map((paragraph, index) => (
              <p
                key={index}
                style={{
                  fontSize: `${bodyFontSize}px`,
                  fontWeight: '300',
                  color: bodyColor,
                  margin: index < paragraphs.length - 1 ? '0 0 24px 0' : '0',
                  lineHeight: '1.7',
                  fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
                }}
              >
                {paragraph}
              </p>
            ))}
          </div>

          {/* Stats */}
          {showStats && stats.length > 0 && (
            <div
              style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fit, minmax(120px, 1fr))',
                gap: '32px',
                paddingTop: '32px',
                borderTop: '1px solid rgba(0,0,0,0.08)'
              }}
            >
              {stats.map((stat, index) => (
                <div key={index}>
                  <div
                    style={{
                      fontSize: '36px',
                      fontWeight: '600',
                      color: statValueColor,
                      marginBottom: '8px',
                      lineHeight: '1',
                      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
                    }}
                  >
                    {stat.value}
                  </div>
                  <div
                    style={{
                      fontSize: '13px',
                      fontWeight: '400',
                      color: statLabelColor,
                      lineHeight: '1.4',
                      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
                    }}
                  >
                    {stat.label}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

