        </div>

        {showScrollIndicator && (
          <div
            style={{
              ...getAnimationStyle(staggerDelay * 3),
              position: 'absolute',
              bottom: '48px',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              gap: '12px',
              animation: shouldAnimate ? 'scrollPulse 2s ease-in-out infinite' : 'none'
            }}
          >
            <span
              style={{
                fontSize: '11px',
                fontWeight: '400',
                letterSpacing: '0.15em',
                textTransform: 'uppercase',
                color: locationColor
              }}
            >
              {scrollText}
            </span>
            <svg
              width="20"
              height="20"
              viewBox="0 0 24 24"
              fill="none"
              stroke={locationColor}
              strokeWidth="1.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <polyline points="6 9 12 15 18 9" />
            </svg>
          </div>
        )}
      </section>
    </>
  );
}

