  const section3Number = config?.section3Number || "03";
  const section3Headline = config?.section3Headline || "Featured Work";
  const section3Body = config?.section3Body || "Selected projects showcasing design thinking, creative problem-solving, and attention to detail.";
  const section3BgColor = config?.section3BgColor || "#171717";
