  const headlineFontWeight = config?.headlineFontWeight || "300";
  const bodyFontSize = parseInt(config?.bodyFontSize || "20");
  const enableScrollSnap = config?.enableScrollSnap !== false;
  const animationDuration = parseInt(config?.animationDuration || "500");
  const enableAnimation = config?.enableAnimation !== false;

  // State management
  const [activeSection, setActiveSection] = React.useState(0);
  const [visibleSections, setVisibleSections] = React.useState([false, false, false, false]);

  // Section refs
  const section1Ref = React.useRef(null);
  const section2Ref = React.useRef(null);
  const section3Ref = React.useRef(null);
  const section4Ref = React.useRef(null);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const shouldAnimate = enableAnimation && !prefersReducedMotion;

  // Intersection Observer for section visibility and active tracking
  React.useEffect(() => {
    const sectionRefs = [section1Ref, section2Ref, section3Ref, section4Ref];

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          const sectionIndex = parseInt(entry.target.dataset.section);

          // Update visibility for animations
          if (entry.isIntersecting && shouldAnimate) {
            setVisibleSections(prev => {
              const newState = [...prev];
              newState[sectionIndex] = true;
              return newState;
            });
          }

          // Update active section (for indicators)
          if (entry.isIntersecting && entry.intersectionRatio >= 0.5) {
            setActiveSection(sectionIndex);
          }
        });
      },
      { 
        threshold: shouldAnimate ? [0.2, 0.5] : [0.5],
        rootMargin: '0px'
      }
    );

    sectionRefs.forEach(ref => {
      if (ref.current) {
        observer.observe(ref.current);
      }
    });

    return () => observer.disconnect();
  }, [shouldAnimate]);

  // Initialize visibility if animations disabled
  React.useEffect(() => {
    if (!shouldAnimate) {
      setVisibleSections([true, true, true, true]);
    }
