            <h1
              style={{
                fontSize: `clamp(${headlineFontSize * 0.5}px, ${headlineFontSize * 0.08}vw + ${headlineFontSize * 0.4}px, ${headlineFontSize}px)`,
                fontWeight: headlineFontWeight,
                lineHeight: '1.1',
                margin: '0 0 32px 0',
                letterSpacing: '-0.02em'
              }}
            >
