                marginLeft: 'auto',
                marginRight: 'auto',
                opacity: 0.8
              }}
            >
              {section1Body}
            </p>
          </div>
        </section>

        {/* Section 2 - Services/About */}
        <section
          ref={section2Ref}
          data-section="1"
          style={{
            ...sectionStyle,
            backgroundColor: section2BgColor,
            color: section2TextColor
          }}
        >
          <div
            style={{
              maxWidth: '900px',
              width: '100%',
              textAlign: 'center',
              ...getAnimationStyle(1)
            }}
          >
            <div
              style={{
