function Component({ config = {} }) {
  const eyebrow = config?.eyebrow || "CREATIVE PROFESSIONAL";
  const headline = config?.headline || "Designing experiences that matter";
  const tagline = config?.tagline || "Strategic designer and creative director specializing in brand identity, digital experiences, and visual storytelling.";
  const ctaText = config?.ctaText || "View Work";
  const ctaUrl = config?.ctaUrl || "#portfolio";
  const secondaryCtaText = config?.secondaryCtaText || "Contact";
  const secondaryCtaUrl = config?.secondaryCtaUrl || "#contact";
  const showVisualPlaceholder = config?.showVisualPlaceholder !== false;
  const backgroundColor = config?.backgroundColor || "#FAFAFA";
  const headlineColor = config?.headlineColor || "#171717";
  const textColor = config?.textColor || "#737373";
  const accentColor = config?.accentColor || "#2563EB";
  const headlineFontSize = parseInt(config?.headlineFontSize || "72");
  const headlineFontWeight = config?.headlineFontWeight || "300";
  const taglineFontSize = parseInt(config?.taglineFontSize || "18");
  const animationDuration = parseInt(config?.animationDuration || "400");
  const staggerDelay = parseInt(config?.staggerDelay || "100");
  const enableAnimation = config?.enableAnimation !== false;

  const [isVisible, setIsVisible] = React.useState(false);
  const sectionRef = React.useRef(null);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const shouldAnimate = enableAnimation && !prefersReducedMotion;

  React.useEffect(() => {
    if (!shouldAnimate) {
      setIsVisible(true);
      return;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setIsVisible(true);
          }
        });
      },
      { threshold: 0.2 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, [shouldAnimate]);

  const getAnimationStyle = (delay = 0) => {
    if (!shouldAnimate) {
      return { opacity: 1, transform: 'translateY(0)' };
    }

    return {
      opacity: isVisible ? 1 : 0,
      transform: isVisible ? 'translateY(0)' : 'translateY(20px)',
      transition: `opacity ${animationDuration}ms ease-out ${delay}ms, transform ${animationDuration}ms ease-out ${delay}ms`
    };
  };

  return (
    <section
      ref={sectionRef}
      className="split-editorial-hero"
      style={{
        backgroundColor: backgroundColor,
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
