      }}
    >
      <div
        style={{
          maxWidth: '1400px',
          margin: '0 auto',
          width: '100%',
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))',
          gap: 'clamp(32px, 5vw, 64px)',
          alignItems: 'center'
        }}
      >
        {/* Content Column */}
        <div style={{ maxWidth: '700px' }}>
          <div style={{ ...getAnimationStyle(0), marginBottom: '24px' }}>
            <span
              style={{
                fontSize: '12px',
                fontWeight: '500',
                letterSpacing: '0.15em',
                textTransform: 'uppercase',
                color: headlineColor,
                display: 'inline-block'
              }}
            >
              {eyebrow}
            </span>
          </div>

          <h1
            style={{
              ...getAnimationStyle(staggerDelay),
              fontSize: `clamp(${headlineFontSize * 0.4}px, ${headlineFontSize * 0.08}vw + ${headlineFontSize * 0.3}px, ${headlineFontSize}px)`,
              fontWeight: headlineFontWeight,
              color: headlineColor,
              lineHeight: '1.1',
              margin: '0 0 32px 0',
              letterSpacing: '-0.02em'
            }}
          >
            {headline}
          </h1>

          <p
            style={{
              ...getAnimationStyle(staggerDelay * 2),
              fontSize: `${taglineFontSize}px`,
              fontWeight: '400',
              color: textColor,
              lineHeight: '1.7',
              margin: '0 0 40px 0',
              maxWidth: '600px'
            }}
          >
            {tagline}
          </p>

          <div
            style={{
              ...getAnimationStyle(staggerDelay * 3),
              display: 'flex',
              flexWrap: 'wrap',
              gap: '16px'
            }}
          >
            <a
              href={ctaUrl}
              style={{
                backgroundColor: accentColor,
                color: '#FFFFFF',
                padding: '16px 32px',
                fontSize: '16px',
                fontWeight: '500',
                textDecoration: 'none',
                borderRadius: '6px',
                display: 'inline-block',
                transition: 'transform 300ms ease-out, box-shadow 300ms ease-out',
                cursor: 'pointer',
                border: 'none',
                boxShadow: `0 4px 16px ${accentColor}30`
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform = 'translateY(-2px)';
                e.currentTarget.style.boxShadow = `0 8px 24px ${accentColor}40`;
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'translateY(0)';
                e.currentTarget.style.boxShadow = `0 4px 16px ${accentColor}30`;
              }}
              onFocus={(e) => {
                e.currentTarget.style.outline = '2px solid currentColor';
                e.currentTarget.style.outlineOffset = '3px';
              }}
              onBlur={(e) => {
                e.currentTarget.style.outline = 'none';
              }}
            >
              {ctaText}
            </a>

            <a
              href={secondaryCtaUrl}
              style={{
                backgroundColor: 'transparent',
                color: headlineColor,
                padding: '16px 32px',
                fontSize: '16px',
                fontWeight: '500',
                textDecoration: 'none',
                borderRadius: '6px',
                border: `1px solid ${headlineColor}`,
                transition: 'background-color 300ms ease-out, color 300ms ease-out',
                cursor: 'pointer'
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.backgroundColor = headlineColor;
                e.currentTarget.style.color = backgroundColor;
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.backgroundColor = 'transparent';
                e.currentTarget.style.color = headlineColor;
              }}
              onFocus={(e) => {
                e.currentTarget.style.outline = '2px solid currentColor';
                e.currentTarget.style.outlineOffset = '3px';
              }}
              onBlur={(e) => {
                e.currentTarget.style.outline = 'none';
              }}
            >
              {secondaryCtaText}
            </a>
          </div>
        </div>

        {/* Visual Column */}
        {showVisualPlaceholder && (
          <div
            style={{
              ...getAnimationStyle(staggerDelay * 4),
              width: '100%',
              minHeight: '400px',
