// STEP 2: Copy this Component function
function Component({ config = {} }) {
  const mainHeadline = config?.mainHeadline || "Multi-Disciplinary Designer";
  const mainSubtext = config?.mainSubtext || "Creating cohesive brand experiences across digital and physical touchpoints.";
  const card1Title = config?.card1Title || "Brand Identity";
  const card1Text = config?.card1Text || "Visual systems that tell your story";
  const card2Title = config?.card2Title || "Digital Design";
  const card2Text = config?.card2Text || "Interfaces that delight users";
  const card3Title = config?.card3Title || "Creative Direction";
  const card3Text = config?.card3Text || "Strategic vision that drives results";
  const card4Title = config?.card4Title || "Web Development";
  const card4Text = config?.card4Text || "Code that brings designs to life";
  const backgroundColor = config?.backgroundColor || "#F5F5F5";
  const cardBackgroundColor = config?.cardBackgroundColor || "#FFFFFF";
  const mainCardBackground = config?.mainCardBackground || "#171717";
  const mainCardTextColor = config?.mainCardTextColor || "#FAFAFA";
  const cardTextColor = config?.cardTextColor || "#171717";
  const accentColor = config?.accentColor || "#737373";
  const mainHeadlineFontSize = parseInt(config?.mainHeadlineFontSize || "48");
  const cardTitleFontSize = parseInt(config?.cardTitleFontSize || "24");
  const enableHoverEffects = config?.enableHoverEffects !== false;
  const animationDuration = parseInt(config?.animationDuration || "400");
  const enableAnimation = config?.enableAnimation !== false;

  const [visibleCards, setVisibleCards] = React.useState([]);
  const sectionRef = React.useRef(null);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const shouldAnimate = enableAnimation && !prefersReducedMotion;

  React.useEffect(() => {
    if (!shouldAnimate) {
      setVisibleCards([0, 1, 2, 3, 4]);
      return;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            // Stagger card animations
            [0, 1, 2, 3, 4].forEach((index) => {
              setTimeout(() => {
                setVisibleCards(prev => [...prev, index]);
              }, index * 100);
            });
          }
        });
      },
      { threshold: 0.1 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, [shouldAnimate]);

  const getCardAnimationStyle = (cardIndex) => {
    if (!shouldAnimate) {
      return { opacity: 1, transform: 'translateY(0)' };
    }

    const isVisible = visibleCards.includes(cardIndex);
    return {
      opacity: isVisible ? 1 : 0,
      transform: isVisible ? 'translateY(0)' : 'translateY(20px)',
      transition: `opacity ${animationDuration}ms ease-out, transform ${animationDuration}ms ease-out`
    };
  };

  const getHoverStyle = (isHovered, isMainCard = false) => {
    if (!enableHoverEffects) return {};

    if (isMainCard) {
      return {
        transform: isHovered ? 'translateY(-4px)' : 'translateY(0)',
        boxShadow: isHovered 
          ? `0 20px 40px ${mainCardBackground}30`
          : `0 8px 24px ${mainCardBackground}20`
      };
    }

    return {
      transform: isHovered ? 'translateY(-4px)' : 'translateY(0)',
      boxShadow: isHovered 
        ? '0 12px 32px rgba(0,0,0,0.12)'
        : '0 4px 16px rgba(0,0,0,0.06)'
    };
  };

  const [hoveredCard, setHoveredCard] = React.useState(null);

  const baseCardStyle = {
    padding: 'clamp(24px, 5vw, 40px)',
    borderRadius: '16px',
    transition: `transform 300ms ease-out, box-shadow 300ms ease-out`
  };

  const cards = [
    { title: card1Title, text: card1Text },
    { title: card2Title, text: card2Text },
    { title: card3Title, text: card3Text },
    { title: card4Title, text: card4Text }
  ];

  return (
    <section
      ref={sectionRef}
      className="bento-grid-hero"
      style={{
        backgroundColor: backgroundColor,
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        padding: 'clamp(48px, 8vw, 80px) clamp(24px, 5vw, 80px)',
        fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif'
      }}
    >
      <div
        style={{
          maxWidth: '1200px',
          margin: '0 auto',
          width: '100%',
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
          gap: '24px'
        }}
      >
        {/* Main Card - Spans 2 columns */}
        <div
          style={{
            ...baseCardStyle,
            ...getCardAnimationStyle(0),
            ...getHoverStyle(hoveredCard === 'main', true),
            gridColumn: 'span 2',
            gridRow: 'span 2',
            backgroundColor: mainCardBackground,
            color: mainCardTextColor,
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'center',
            minHeight: '400px'
          }}
          onMouseEnter={() => setHoveredCard('main')}
          onMouseLeave={() => setHoveredCard(null)}
        >
          <h1
            style={{
              fontSize: `clamp(${mainHeadlineFontSize * 0.6}px, ${mainHeadlineFontSize * 0.08}vw + ${mainHeadlineFontSize * 0.4}px, ${mainHeadlineFontSize}px)`,
              fontWeight: '500',
              lineHeight: '1.2',
              margin: '0 0 20px 0',
              letterSpacing: '-0.02em'
            }}
          >
            {mainHeadline}
          </h1>
          <p
            style={{
              fontSize: '18px',
              fontWeight: '400',
              lineHeight: '1.6',
              margin: 0,
              opacity: 0.9
            }}
          >
            {mainSubtext}
          </p>
        </div>

        {/* Small Cards */}
        {cards.map((card, index) => (
          <div
            key={index}
            style={{
              ...baseCardStyle,
              ...getCardAnimationStyle(index + 1),
              ...getHoverStyle(hoveredCard === index),
              backgroundColor: cardBackgroundColor,
              color: cardTextColor,
              cursor: 'pointer'
            }}
            onMouseEnter={() => setHoveredCard(index)}
            onMouseLeave={() => setHoveredCard(null)}
          >
            <h3
              style={{
                fontSize: `${cardTitleFontSize}px`,
                fontWeight: '500',
                lineHeight: '1.3',
                margin: '0 0 12px 0',
                letterSpacing: '-0.01em'
              }}
            >
              {card.title}
            </h3>
            <p
              style={{
                fontSize: '15px',
                fontWeight: '400',
                lineHeight: '1.5',
                margin: 0,
                color: accentColor
              }}
            >
              {card.text}
            </p>
          </div>
        ))}
      </div>
    </section>
  );
}

