// ============================================================================
// HERO #7: ANIMATED NAME REVEAL - COMPLETE IMPLEMENTATION
// ============================================================================
// Text scramble animation effect for dynamic entrance
// Perfect for: Tech portfolios, developers, futuristic brands
// ============================================================================

// STEP 1: Copy this MANIFEST object
const MANIFEST = {
  "type": "PersonalWebsite.AnimatedNameReveal",
  "description": "Dynamic hero with character scramble animation that resolves to reveal your name. Creates a memorable, tech-forward first impression.",
  "editorElement": {
    "selector": ".animated-name-reveal-hero",
    "displayName": "Animated Name Reveal Hero",
    "archetype": "container",
    "data": {
      "name": {
        "dataType": "text",
        "displayName": "Name to Reveal",
        "defaultValue": "ALEX MORGAN",
        "group": "Content"
      },
      "title": {
        "dataType": "text",
        "displayName": "Title/Role",
        "defaultValue": "Full-Stack Developer",
        "group": "Content"
      },
      "description": {
        "dataType": "text",
        "displayName": "Description",
        "defaultValue": "Building intelligent systems and beautiful interfaces",
        "group": "Content"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#0A0A0A",
        "group": "Colors"
      },
      "nameColor": {
        "dataType": "color",
        "displayName": "Name Color",
        "defaultValue": "#00FF88",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#A3A3A3",
        "group": "Colors"
      },
      "nameFontSize": {
        "dataType": "number",
        "displayName": "Name Font Size (px)",
        "defaultValue": 80,
        "group": "Typography"
      },
      "useMonospace": {
        "dataType": "booleanValue",
        "displayName": "Use Monospace Font",
        "defaultValue": true,
        "group": "Typography"
      },
      "scrambleDuration": {
        "dataType": "select",
        "displayName": "Scramble Duration (ms)",
        "defaultValue": "2000",
        "options": ["1500", "2000", "2500", "3000"],
        "group": "Animation"
      },
      "enableScramble": {
        "dataType": "booleanValue",
        "displayName": "Enable Scramble Animation",
        "defaultValue": true,
        "group": "Animation"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

// STEP 2: Copy this Component function
function Component({ config = {} }) {
  const targetName = config?.name || "ALEX MORGAN";
  const title = config?.title || "Full-Stack Developer";
  const description = config?.description || "Building intelligent systems and beautiful interfaces";
  const backgroundColor = config?.backgroundColor || "#0A0A0A";
  const nameColor = config?.nameColor || "#00FF88";
  const textColor = config?.textColor || "#A3A3A3";
  const nameFontSize = parseInt(config?.nameFontSize || "80");
  const useMonospace = config?.useMonospace !== false;
  const scrambleDuration = parseInt(config?.scrambleDuration || "2000");
  const enableScramble = config?.enableScramble !== false;

  const [displayName, setDisplayName] = React.useState("");
  const [isScrambling, setIsScrambling] = React.useState(true);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const shouldScramble = enableScramble && !prefersReducedMotion;

  // Character pool for scrambling
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789@#$%&*";

  React.useEffect(() => {
    if (!shouldScramble) {
      setDisplayName(targetName);
      setIsScrambling(false);
      return;
    }

    let frame = 0;
    const totalFrames = Math.floor(scrambleDuration / 50); // 50ms per frame
    const nameLength = targetName.length;

    const scrambleInterval = setInterval(() => {
      frame++;

      // Calculate how many characters should be revealed
      const revealCount = Math.floor((frame / totalFrames) * nameLength);

      // Build the display string
      let newDisplay = "";
      for (let i = 0; i < nameLength; i++) {
        if (i < revealCount) {
          // Character is revealed
          newDisplay += targetName[i];
        } else if (targetName[i] === " ") {
          // Keep spaces as spaces
          newDisplay += " ";
        } else {
          // Character is still scrambling
          newDisplay += chars[Math.floor(Math.random() * chars.length)];
        }
      }

      setDisplayName(newDisplay);

      // Stop when complete
      if (frame >= totalFrames) {
        clearInterval(scrambleInterval);
        setDisplayName(targetName);
        setIsScrambling(false);
      }
    }, 50);

    return () => clearInterval(scrambleInterval);
  }, [targetName, scrambleDuration, shouldScramble]);

  const fontFamily = useMonospace
    ? '"Courier New", Courier, monospace'
    : '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif';

  return (
    <section
      className="animated-name-reveal-hero"
      style={{
        backgroundColor: backgroundColor,
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: 'clamp(48px, 8vw, 80px) clamp(24px, 5vw, 80px)',
        fontFamily: fontFamily,
        textAlign: 'center',
        position: 'relative',
        overflow: 'hidden'
      }}
    >
      {/* Scanline effect */}
      <div
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(255,255,255,0.03) 2px, rgba(255,255,255,0.03) 4px)',
          pointerEvents: 'none',
          opacity: 0.5
        }}
      />

      <div
        style={{
          maxWidth: '900px',
          width: '100%',
          position: 'relative',
          zIndex: 1
        }}
      >
        {/* Animated Name */}
        <h1
          style={{
            fontSize: `clamp(${nameFontSize * 0.4}px, ${nameFontSize * 0.08}vw + ${nameFontSize * 0.3}px, ${nameFontSize}px)`,
            fontWeight: '700',
            color: nameColor,
            lineHeight: '1.1',
            margin: '0 0 24px 0',
            letterSpacing: useMonospace ? '0.05em' : '-0.02em',
            textShadow: `0 0 20px ${nameColor}60`,
            minHeight: '1.1em' // Prevent layout shift
          }}
        >
          {displayName || "\u00A0"}
          {isScrambling && (
            <span
              style={{
                display: 'inline-block',
                width: '0.1em',
                height: '1em',
                backgroundColor: nameColor,
                marginLeft: '0.1em',
                animation: 'blink 1s step-end infinite'
              }}
            />
          )}
        </h1>

        <style>{`
          @keyframes blink {
            50% { opacity: 0; }
          }
        `}</style>

        {/* Title */}
        <p
          style={{
            fontSize: 'clamp(18px, 3vw, 24px)',
            fontWeight: '500',
            color: textColor,
            lineHeight: '1.5',
            margin: '0 0 16px 0',
            textTransform: 'uppercase',
            letterSpacing: '0.15em',
            opacity: isScrambling ? 0 : 1,
            transition: 'opacity 600ms ease-out 200ms'
          }}
        >
          {title}
        </p>

        {/* Description */}
        <p
          style={{
            fontSize: 'clamp(16px, 2.5vw, 18px)',
            fontWeight: '400',
            color: textColor,
            lineHeight: '1.7',
            margin: 0,
            opacity: isScrambling ? 0 : 0.7,
            transition: 'opacity 600ms ease-out 400ms'
          }}
        >
          {description}
        </p>

        {/* Decorative Corners */}
        <div
          style={{
            position: 'absolute',
            top: '-20px',
            left: '-20px',
            width: '40px',
            height: '40px',
            borderTop: `2px solid ${nameColor}`,
            borderLeft: `2px solid ${nameColor}`,
            opacity: isScrambling ? 0 : 0.5,
            transition: 'opacity 600ms ease-out 600ms'
          }}
        />
        <div
          style={{
            position: 'absolute',
            top: '-20px',
            right: '-20px',
            width: '40px',
            height: '40px',
            borderTop: `2px solid ${nameColor}`,
            borderRight: `2px solid ${nameColor}`,
            opacity: isScrambling ? 0 : 0.5,
            transition: 'opacity 600ms ease-out 600ms'
          }}
        />
        <div
          style={{
            position: 'absolute',
            bottom: '-20px',
            left: '-20px',
            width: '40px',
            height: '40px',
            borderBottom: `2px solid ${nameColor}`,
            borderLeft: `2px solid ${nameColor}`,
            opacity: isScrambling ? 0 : 0.5,
            transition: 'opacity 600ms ease-out 600ms'
          }}
        />
        <div
          style={{
            position: 'absolute',
            bottom: '-20px',
            right: '-20px',
            width: '40px',
            height: '40px',
            borderBottom: `2px solid ${nameColor}`,
            borderRight: `2px solid ${nameColor}`,
            opacity: isScrambling ? 0 : 0.5,
            transition: 'opacity 600ms ease-out 600ms'
          }}
        />
      </div>
    </section>
  );
}

