        <div style={styles.servicesList}>
          {services.map((service, index) => (
            <span key={index} style={styles.serviceItem(index)}>{service.trim()}</span>
          ))}
        </div>
      </section>

      <section style={styles.ctaSection} ref={setSectionRef(6)}>
        <h2 style={styles.ctaTitle}>{ctaText}</h2>
        <button 
          style={styles.ctaButton}
          onMouseEnter={(e) => {
            e.target.style.backgroundColor = primaryTextColor;
            e.target.style.color = backgroundColor;
          }}
          onMouseLeave={(e) => {
            e.target.style.backgroundColor = 'transparent';
            e.target.style.color = primaryTextColor;
          }}
        >
          צרו קשר
          <ArrowIcon />
        </button>
      </section>

      <footer style={styles.footer}>
        <span>© {new Date().getFullYear()} {companyName}</span>
      </footer>
    </div>
  );
}

