function Component({ config = {} }) {
  const [scrollY, setScrollY] = React.useState(0);
  const [visibleSections, setVisibleSections] = React.useState(new Set([0]));
  const sectionRefs = React.useRef([]);

  const backgroundColor = config?.backgroundColor || '#FAFAFA';
  const darkSection = config?.darkSection || '#18181B';
  const primaryText = config?.primaryText || '#18181B';
  const secondaryText = config?.secondaryText || '#71717A';
  const accentColor = config?.accentColor || '#A1A1AA';

  const companyName = config?.companyName || 'ארקייד גיימס';
  const heroLine1 = config?.heroLine1 || 'אנחנו מביאים';
  const heroLine2 = config?.heroLine2 || 'את החוויה';
  const heroLine3 = config?.heroLine3 || 'האולטימטיבית';
  const storyText = config?.storyText || 'חברת ארקייד גיימס נוסדה בשנת 2008 ומתמחה ביבוא ובשיווק מכונות משחק ושעשוע איכותיות ובטיחותיות.';
  const missionText = config?.missionText || 'כחברה מובילה בתחומה משווקת מכונות משחק המיוצרות בשווקים בינלאומיים.';
  const servicesText = config?.servicesText || 'החברה מציעה בנוסף שירותי התקנה ותחזוקה של המכונות.';
  const consultingText = config?.consultingText || 'מספקת שירותי ייעוץ וליווי בתחום מכונות המשחק.';

  const capabilities = [
    { num: '01', title: 'יבוא ושיווק', desc: 'מכונות משחק מהשווקים הבינלאומיים המובילים' },
    { num: '02', title: 'התקנה ותחזוקה', desc: 'שירות מקצועי ומהיר בכל רחבי הארץ' },
    { num: '03', title: 'ייעוץ עסקי', desc: 'ליווי מקצועי מהתכנון ועד ההפעלה' },
    { num: '04', title: 'הדרכה', desc: 'הכשרה מלאה לצוותים ומפעילים' }
  ];

  const clients = [
    'קניונים', 'משחקיות', 'ברים', 'אולמות משחק',
    'חברות הייטק מובילות', 'חברות הפקה', 'ועדי עובדים'
  ];

  React.useEffect(() => {
    const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (prefersReducedMotion) {
      setVisibleSections(new Set([0, 1, 2, 3, 4]));
      return;
    }

    const handleScroll = () => setScrollY(window.scrollY);
    window.addEventListener('scroll', handleScroll, { passive: true });

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const index = parseInt(entry.target.dataset.index);
            setVisibleSections(prev => new Set([...prev, index]));
          }
        });
      },
      { threshold: 0.2 }
    );

    sectionRefs.current.forEach((ref) => {
      if (ref) observer.observe(ref);
    });

    return () => {
      window.removeEventListener('scroll', handleScroll);
      observer.disconnect();
    };
  }, []);

  const getIcon = (iconName, size = 24) => {
    const icons = {
      ArrowDown: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><path d="M12 5v14"/><path d="m19 12-7 7-7-7"/></svg>,
      ArrowUpRight: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><path d="M7 7h10v10"/><path d="M7 17 17 7"/></svg>,
      Play: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><polygon points="5 3 19 12 5 21 5 3"/></svg>
    };
    return icons[iconName] || null;
  };

  const keyframes = `
    @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+Hebrew:wght@300;400;500;600&display=swap');

    @keyframes fadeInUp {
      from {
        opacity: 0;
        transform: translateY(60px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    @keyframes slideFromRight {
      from {
        opacity: 0;
        transform: translateX(-40px);
      }
      to {
        opacity: 1;
        transform: translateX(0);
      }
    }

    @keyframes revealLine {
      from { width: 0; }
      to { width: 100%; }
    }
  `;

  return (
    <div
      className="about-split"
      dir="rtl"
      style={{
        fontFamily: "'Noto Sans Hebrew', sans-serif",
        backgroundColor: backgroundColor,
        color: primaryText,
        minHeight: '100vh'
      }}
    >
      <style>{keyframes}</style>

      {/* Fixed Header */}
      <header style={{
        position: 'fixed',
        top: 0,
        right: 0,
        left: 0,
        zIndex: 100,
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        padding: '24px 48px',
        backgroundColor: scrollY > 100 ? backgroundColor : 'transparent',
        transition: 'background-color 0.3s ease'
      }}>
        <div style={{
          fontSize: '16px',
          fontWeight: '500'
        }}>
