      left: '50%',
      transform: 'translate(-50%, -50%)',
      width: '100%',
      height: '100%',
      pointerEvents: 'none'
    },
    heroCircle: (size, delay) => ({
      position: 'absolute',
      top: '50%',
      left: '50%',
      width: size + 'px',
      height: size + 'px',
      border: `1px solid ${circleColor}`,
      borderRadius: '50%',
      transform: 'translate(-50%, -50%)',
      opacity: isVisible(0) ? 1 : 0,
      transition: `opacity 0.8s ease ${delay}s`
    }),
    heroContent: {
      textAlign: 'center',
      position: 'relative',
      zIndex: 2
    },
    heroSubtitle: {
      fontSize: '13px',
      fontWeight: '400',
      letterSpacing: '0.2em',
      color: secondaryTextColor,
      marginBottom: '24px',
      textTransform: 'uppercase',
      opacity: isVisible(0) ? 1 : 0,
      transition: 'opacity 0.6s ease 0.2s'
    },
    heroTitle: {
      fontSize: 'clamp(48px, 10vw, 120px)',
      fontWeight: '300',
      lineHeight: '1.1',
      marginBottom: '48px',
      opacity: isVisible(0) ? 1 : 0,
      transform: isVisible(0) ? 'scale(1)' : 'scale(0.9)',
      transition: 'all 0.8s cubic-bezier(0.22, 1, 0.36, 1)'
    },
    scrollIndicator: {
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      gap: '8px',
      fontSize: '12px',
      color: secondaryTextColor,
      opacity: isVisible(0) ? 1 : 0,
