      transform: 'translate(-50%, -50%)',
      width: '200px',
      height: '200px',
      backgroundColor: accentColor,
      borderRadius: '50%',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      color: backgroundColor,
      opacity: isVisible(1) ? 1 : 0,
      transition: 'opacity 0.6s ease'
    },
    statsCenterValue: {
      fontSize: '48px',
      fontWeight: '300',
