    },
    statsCenterLabel: {
      fontSize: '13px',
      opacity: 0.7,
      marginTop: '8px'
    },
    statOrbit: (index) => {
      const angle = (index * 90) * (Math.PI / 180);
      const radius = 200;
      const x = Math.cos(angle) * radius;
