function Component({ config = {} }) {
  const [visibleSections, setVisibleSections] = React.useState(new Set());
  const sectionRefs = React.useRef([]);

  const companyName = config?.companyName || 'ארקייד גיימס';
  const heroTitle = config?.heroTitle || 'מובילים את תעשיית הבידור';
  const heroYear = config?.heroYear || '2008';
  const aboutText = config?.aboutText || 'חברת ארקייד גיימס נוסדה בשנת 2008.';
  const visionText = config?.visionText || 'להביא את חוויית הבידור המתקדמת.';
  const stat1Value = config?.stat1Value || '20+';
  const stat1Label = config?.stat1Label || 'שנות ניסיון';
  const stat2Value = config?.stat2Value || '100+';
  const stat2Label = config?.stat2Label || 'לקוחות';
  const stat3Value = config?.stat3Value || '#1';
  const stat3Label = config?.stat3Label || 'בישראל';
  const products = (config?.products || 'מכונות משחק,מכונות בובות').split(',');
  const services = (config?.services || 'התקנה,תחזוקה,ייעוץ').split(',');
  const clients = (config?.clients || 'קניונים,משחקיות,ברים').split(',');
  const ctaTitle = config?.ctaTitle || 'בואו נדבר';
  const ctaButton = config?.ctaButton || 'צרו קשר';

  const backgroundColor = config?.backgroundColor || '#FFFFFF';
  const primaryTextColor = config?.primaryTextColor || '#1A1A1A';
  const secondaryTextColor = config?.secondaryTextColor || '#6B6B6B';
  const stripeColor = config?.stripeColor || '#F5F5F5';
  const accentColor = config?.accentColor || '#1A1A1A';

  const stats = [
    { value: stat1Value, label: stat1Label },
    { value: stat2Value, label: stat2Label },
    { value: stat3Value, label: stat3Label }
  ];

  React.useEffect(() => {
    const observers = [];
    sectionRefs.current.forEach((ref, index) => {
      if (ref) {
        const observer = new IntersectionObserver(
          ([entry]) => {
            if (entry.isIntersecting) {
              setVisibleSections(prev => new Set([...prev, index]));
            }
          },
          { threshold: 0.15 }
        );
        observer.observe(ref);
        observers.push(observer);
      }
    });
    return () => observers.forEach(obs => obs.disconnect());
  }, []);

  const setSectionRef = (index) => (el) => {
    sectionRefs.current[index] = el;
  };

  const isVisible = (index) => visibleSections.has(index);

  const ArrowIcon = () => (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <line x1="7" y1="17" x2="17" y2="7" />
      <polyline points="7 7 17 7 17 17" />
    </svg>
  );

  const styles = {
    page: {
      fontFamily: '"Noto Sans Hebrew", sans-serif',
      direction: 'rtl',
      backgroundColor: backgroundColor,
      color: primaryTextColor,
      minHeight: '100vh',
      position: 'relative'
    },
    stripes: {
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      display: 'grid',
      gridTemplateColumns: 'repeat(12, 1fr)',
      pointerEvents: 'none',
      zIndex: 0
    },
    stripe: (index) => ({
      backgroundColor: index % 2 === 0 ? stripeColor : 'transparent',
      height: '100%'
    }),
    content: {
      position: 'relative',
      zIndex: 1
    },
    header: {
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      padding: '32px 48px',
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      zIndex: 100,
      backgroundColor: 'rgba(255, 255, 255, 0.95)',
      backdropFilter: 'blur(10px)'
    },
    logo: {
      fontSize: '15px',
      fontWeight: '500'
    },
    hero: {
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'flex-end',
      padding: '120px 48px 100px'
    },
    heroContent: {
      display: 'grid',
      gridTemplateColumns: 'repeat(12, 1fr)',
      gap: '24px',
      width: '100%'
    },
    heroYear: {
      gridColumn: '1 / 4',
      fontSize: 'clamp(100px, 15vw, 200px)',
      fontWeight: '300',
      lineHeight: '0.8',
      opacity: isVisible(0) ? 0.1 : 0,
      transition: 'opacity 0.8s ease'
    },
    heroTitle: {
