function Component({ config = {} }) {
  const [visibleSections, setVisibleSections] = React.useState(new Set());
  const sectionRefs = React.useRef([]);

  const companyName = config?.companyName || 'ארקייד גיימס';
  const heroTitle = config?.heroTitle || 'חוויית בידור מהעתיד';
  const heroSubtitle = config?.heroSubtitle || 'מובילים את תעשיית הבידור בישראל מאז 2008';
  const heroImage = config?.heroImage || 'https://images.unsplash.com/photo-1511882150382-421056c89033?w=800&q=80';
  const aboutImage = config?.aboutImage || 'https://images.unsplash.com/photo-1478737270239-2f02b77fc618?w=600&q=80';
  const aboutText = config?.aboutText || 'חברת ארקייד גיימס נוסדה בשנת 2008.';
  const visionText = config?.visionText || 'להביא את חוויית הבידור המתקדמת.';
  const stat1Value = config?.stat1Value || '2008';
  const stat1Label = config?.stat1Label || 'שנת הקמה';
  const stat2Value = config?.stat2Value || '20+';
  const stat2Label = config?.stat2Label || 'שנות ניסיון';
  const stat3Value = config?.stat3Value || '100+';
  const stat3Label = config?.stat3Label || 'לקוחות';
  const stat4Value = config?.stat4Value || '#1';
  const stat4Label = config?.stat4Label || 'בישראל';
  const productImages = (config?.productImages || '').split(',').filter(Boolean);
  const products = (config?.products || 'מכונות משחק,מכונות בובות').split(',');
  const services = (config?.services || 'התקנה,תחזוקה,ייעוץ').split(',');
  const clients = (config?.clients || 'קניונים,משחקיות,ברים').split(',');
  const ctaTitle = config?.ctaTitle || 'בואו ניצור משהו יחד';
  const ctaButton = config?.ctaButton || 'צרו קשר';

  const gradientColor1 = config?.gradientColor1 || '#E8E4DF';
  const gradientColor2 = config?.gradientColor2 || '#DFE8E4';
  const gradientColor3 = config?.gradientColor3 || '#E4DFE8';
  const primaryTextColor = config?.primaryTextColor || '#1A1A1A';
  const secondaryTextColor = config?.secondaryTextColor || '#6B6B6B';
  const cardBackground = config?.cardBackground || 'rgba(255,255,255,0.7)';
  const accentColor = config?.accentColor || '#1A1A1A';

  const stats = [
    { value: stat1Value, label: stat1Label },
    { value: stat2Value, label: stat2Label },
    { value: stat3Value, label: stat3Label },
    { value: stat4Value, label: stat4Label }
  ];

  React.useEffect(() => {
    const observers = [];
    sectionRefs.current.forEach((ref, index) => {
      if (ref) {
        const observer = new IntersectionObserver(
          ([entry]) => {
            if (entry.isIntersecting) {
              setVisibleSections(prev => new Set([...prev, index]));
            }
          },
          { threshold: 0.15 }
        );
        observer.observe(ref);
        observers.push(observer);
      }
    });
    return () => observers.forEach(obs => obs.disconnect());
  }, []);

  const setSectionRef = (index) => (el) => {
    sectionRefs.current[index] = el;
  };

  const isVisible = (index) => visibleSections.has(index);

  const ArrowIcon = () => (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <line x1="7" y1="17" x2="17" y2="7" />
      <polyline points="7 7 17 7 17 17" />
    </svg>
  );

