      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      background: `
        radial-gradient(ellipse 80% 50% at 20% 40%, ${gradientColor1} 0%, transparent 50%),
        radial-gradient(ellipse 60% 80% at 80% 20%, ${gradientColor2} 0%, transparent 50%),
        radial-gradient(ellipse 70% 60% at 40% 90%, ${gradientColor3} 0%, transparent 50%),
        linear-gradient(180deg, #FAFAFA 0%, #F5F5F5 100%)
      `,
      zIndex: 0
    },
    content: {
      position: 'relative',
      zIndex: 1
    },
    header: {
      position: 'fixed',
      top: 0,
      left: 0,
