function Component({ config = {} }) {
  const [visible, setVisible] = React.useState({});
  const sectionRefs = React.useRef({});

  const pageLabel = config?.pageLabel || "אודות";
  const heroTitle = config?.heroTitle || "ארקייד גיימס";
  const heroSubtitle = config?.heroSubtitle || "מכונות משחק ושעשוע";
  const introText = config?.introText || "חברת ארקייד גיימס נוסדה בשנת 2008 ומתמחה ביבוא ובשיווק מכונות משחק ושעשוע איכותיות ובטיחותיות.";

  const expertiseTitle = config?.expertiseTitle || "התמחויות";
  const expertiseList = [
    config?.expertise1 || "מכונות משחק",
    config?.expertise2 || "מכונות בובות",
    config?.expertise3 || "מכונות ספורט",
    config?.expertise4 || "מכונות רכיבה",
    config?.expertise5 || "משחקי סימולטור",
    config?.expertise6 || "מתקני שעשוע"
  ];

  const servicesTitle = config?.servicesTitle || "שירותים";
  const services = [
    { title: config?.service1Title || "התקנה ותחזוקה", desc: config?.service1Desc || "שירותי התקנה ותחזוקה מקצועיים" },
    { title: config?.service2Title || "ייעוץ וליווי", desc: config?.service2Desc || "ייעוץ והדרכה בבחירת מיקום והתאמת תוכן" },
    { title: config?.service3Title || "ליווי עסקי", desc: config?.service3Desc || "ליווי עסקי מקיף מההתחלה ועד להפעלה" }
  ];

  const clientsTitle = config?.clientsTitle || "לקוחות";
  const clientsList = config?.clientsList || "קניונים, משחקיות, ברים, אולמות משחק, חברות הייטק";
  const ctaText = config?.ctaText || "צור קשר";

  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const textColor = config?.textColor || "#18181B";
  const mutedColor = config?.mutedColor || "#71717A";
  const borderColor = config?.borderColor || "#E4E4E7";
  const accentColor = config?.accentColor || "#18181B";

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setVisible(prev => ({ ...prev, [entry.target.id]: true }));
          }
        });
      },
      { threshold: 0.1 }
    );

    Object.values(sectionRefs.current).forEach(ref => {
      if (ref) observer.observe(ref);
    });

    return () => observer.disconnect();
  }, []);

  return (
    <div className="about-swiss" style={{
      fontFamily: '"Noto Sans Hebrew", "Noto Sans", sans-serif',
      backgroundColor,
      color: textColor,
      minHeight: '100vh',
      direction: 'rtl'
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+Hebrew:wght@300;400;500&display=swap');

        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }

        .swiss-animate {
          animation: fadeIn 0.6s ease-out forwards;
          opacity: 0;
        }

        .swiss-grid {
          display: grid;
          grid-template-columns: 200px 1fr;
          gap: 80px;
          padding: 60px 80px;
          border-bottom: 1px solid ${borderColor};
        }

        @media (max-width: 768px) {
          .swiss-grid {
            grid-template-columns: 1fr;
            gap: 30px;
            padding: 40px 30px;
          }
        }
      `}</style>

      {/* Header */}
      <header style={{
        padding: '40px 80px',
        borderBottom: `1px solid ${borderColor}`,
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center'
      }}>
        <span style={{
          fontSize: '12px',
          fontWeight: 500,
          letterSpacing: '0.1em',
          color: mutedColor
        }}>
          {pageLabel}
        </span>
        <button style={{
          backgroundColor: 'transparent',
          border: `1px solid ${textColor}`,
          padding: '10px 24px',
          fontSize: '13px',
          fontWeight: 500,
          cursor: 'pointer',
          color: textColor,
          transition: 'all 0.3s ease'
        }}
        onMouseEnter={e => {
          e.target.style.backgroundColor = textColor;
          e.target.style.color = backgroundColor;
        }}
        onMouseLeave={e => {
          e.target.style.backgroundColor = 'transparent';
          e.target.style.color = textColor;
        }}
        >
          {ctaText}
        </button>
      </header>

      {/* Hero Section */}
      <section 
        id="hero"
        ref={el => sectionRefs.current.hero = el}
        style={{
          padding: '120px 80px',
          borderBottom: `1px solid ${borderColor}`
        }}
      >
        <h1 className={visible.hero ? 'swiss-animate' : ''} style={{
          fontSize: 'clamp(48px, 10vw, 120px)',
          fontWeight: 300,
          lineHeight: 0.95,
          letterSpacing: '-0.02em',
          marginBottom: '20px'
        }}>
          {heroTitle}
        </h1>
        <p className={visible.hero ? 'swiss-animate' : ''} style={{
          fontSize: '18px',
          fontWeight: 400,
          color: mutedColor,
          animationDelay: '0.1s'
        }}>
          {heroSubtitle}
        </p>
      </section>

      {/* Intro Section */}
      <section 
        id="intro"
        ref={el => sectionRefs.current.intro = el}
        className="swiss-grid"
      >
        <div>
          <span style={{
            fontSize: '12px',
            fontWeight: 500,
            color: mutedColor,
            letterSpacing: '0.05em'
          }}>
            01
          </span>
        </div>
        <p className={visible.intro ? 'swiss-animate' : ''} style={{
          fontSize: 'clamp(20px, 2.5vw, 28px)',
          fontWeight: 400,
          lineHeight: 1.6,
          maxWidth: '800px'
        }}>
          {introText}
        </p>
      </section>

      {/* Expertise Section */}
      <section 
        id="expertise"
        ref={el => sectionRefs.current.expertise = el}
        className="swiss-grid"
      >
        <div>
          <span style={{
            fontSize: '12px',
            fontWeight: 500,
            color: mutedColor,
            letterSpacing: '0.05em',
            display: 'block',
            marginBottom: '8px'
          }}>
            02
          </span>
          <h2 style={{
            fontSize: '14px',
            fontWeight: 500,
            letterSpacing: '0.05em'
          }}>
            {expertiseTitle}
          </h2>
        </div>
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fill, minmax(180px, 1fr))',
          gap: '20px'
        }}>
          {expertiseList.map((item, index) => (
            <div 
              key={index}
              className={visible.expertise ? 'swiss-animate' : ''}
              style={{
                fontSize: '16px',
                fontWeight: 400,
                padding: '16px 0',
                borderBottom: `1px solid ${borderColor}`,
                animationDelay: `${index * 0.05}s`
              }}
            >
              {item}
            </div>
          ))}
        </div>
      </section>

      {/* Services Section */}
      <section 
        id="services"
        ref={el => sectionRefs.current.services = el}
        className="swiss-grid"
      >
        <div>
          <span style={{
            fontSize: '12px',
            fontWeight: 500,
            color: mutedColor,
            letterSpacing: '0.05em',
            display: 'block',
            marginBottom: '8px'
          }}>
            03
          </span>
          <h2 style={{
            fontSize: '14px',
            fontWeight: 500,
            letterSpacing: '0.05em'
          }}>
            {servicesTitle}
          </h2>
        </div>
        <div style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '40px'
        }}>
          {services.map((service, index) => (
            <div 
              key={index}
              className={visible.services ? 'swiss-animate' : ''}
              style={{
                animationDelay: `${index * 0.1}s`
              }}
            >
              <h3 style={{
                fontSize: '20px',
                fontWeight: 500,
                marginBottom: '8px'
              }}>
                {service.title}
              </h3>
              <p style={{
                fontSize: '15px',
                fontWeight: 400,
                color: mutedColor,
                lineHeight: 1.6,
                maxWidth: '500px'
              }}>
                {service.desc}
              </p>
            </div>
          ))}
        </div>
      </section>

      {/* Clients Section */}
      <section 
        id="clients"
        ref={el => sectionRefs.current.clients = el}
        className="swiss-grid"
      >
        <div>
          <span style={{
            fontSize: '12px',
            fontWeight: 500,
            color: mutedColor,
            letterSpacing: '0.05em',
            display: 'block',
            marginBottom: '8px'
          }}>
            04
          </span>
          <h2 style={{
            fontSize: '14px',
            fontWeight: 500,
            letterSpacing: '0.05em'
          }}>
            {clientsTitle}
          </h2>
        </div>
        <p className={visible.clients ? 'swiss-animate' : ''} style={{
          fontSize: '16px',
          fontWeight: 400,
          color: mutedColor,
          lineHeight: 1.8
        }}>
          {clientsList}
        </p>
      </section>

      {/* Footer CTA */}
      <section style={{
        padding: '80px',
        display: 'flex',
        justifyContent: 'center'
      }}>
        <button style={{
          backgroundColor: accentColor,
          color: backgroundColor,
          border: 'none',
          padding: '18px 48px',
          fontSize: '14px',
          fontWeight: 500,
          cursor: 'pointer',
          transition: 'transform 0.3s ease, opacity 0.3s ease'
        }}
        onMouseEnter={e => {
          e.target.style.transform = 'translateY(-2px)';
          e.target.style.opacity = '0.9';
        }}
        onMouseLeave={e => {
          e.target.style.transform = 'translateY(0)';
          e.target.style.opacity = '1';
        }}
        >
          {ctaText}
        </button>
      </section>
    </div>
  );
}

