function Component({ config = {} }) {
  const [scrollY, setScrollY] = React.useState(0);
  const [visibleSections, setVisibleSections] = React.useState(new Set(['hero']));
  const [hoveredService, setHoveredService] = React.useState(null);
  const containerRef = React.useRef(null);

  const heroStatement = config?.heroStatement || "We make brands impossible to ignore.";
  const subStatement = config?.subStatement || "A creative studio obsessed with craft, driven by curiosity, and committed to making work that matters.";
  const beliefTitle = config?.beliefTitle || "What We Believe";
  const beliefText = config?.beliefText || "Good design isn't decoration. It's communication distilled to its purest form. We strip away the noise to reveal what truly resonates.";
  const stat1Value = config?.stat1Value || "2016";
  const stat1Label = config?.stat1Label || "Founded";
  const stat2Value = config?.stat2Value || "23";
  const stat2Label = config?.stat2Label || "Creatives";
  const stat3Value = config?.stat3Value || "∞";
  const stat3Label = config?.stat3Label || "Possibilities";
  const ctaText = config?.ctaText || "Start a Project";

  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const textDark = config?.textDark || "#0A0A0A";
  const textMuted = config?.textMuted || "#717171";
  const accentColor = config?.accentColor || "#0A0A0A";
  const headingFont = config?.headingFont || "'Space Grotesk', system-ui, sans-serif";
  const heroSize = config?.heroSize || 96;

  const services = [
    { num: "01", title: "Brand Strategy", desc: "Foundation that guides every decision" },
    { num: "02", title: "Visual Identity", desc: "Systems that scale and flex" },
    { num: "03", title: "Digital Experience", desc: "Interactions that feel inevitable" },
    { num: "04", title: "Motion Design", desc: "Movement that tells stories" }
  ];

  const team = [
    { name: "Sarah Cole", role: "Founder & CEO" },
    { name: "Marcus Webb", role: "Creative Director" },
    { name: "Aiko Tanaka", role: "Head of Strategy" },
    { name: "David Park", role: "Design Lead" },
    { name: "Emma Larsson", role: "Motion Director" },
    { name: "Jay Williams", role: "Tech Lead" }
  ];

  React.useEffect(() => {
    const handleScroll = () => {
      if (containerRef.current) {
        setScrollY(containerRef.current.scrollTop);
      }
    };

    const container = containerRef.current;
    if (container) {
      container.addEventListener('scroll', handleScroll);
      return () => container.removeEventListener('scroll', handleScroll);
    }
  }, []);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setVisibleSections(prev => new Set([...prev, entry.target.dataset.section]));
          }
        });
      },
      { threshold: 0.1, root: containerRef.current }
    );

    const sections = containerRef.current?.querySelectorAll('[data-section]');
    sections?.forEach(section => observer.observe(section));

    return () => observer.disconnect();
  }, []);

  const isVisible = (section) => visibleSections.has(section);

  return (
    <div 
      ref={containerRef}
      className="about-bold-minimal" 
      style={{
        fontFamily: "'Inter', system-ui, sans-serif",
        backgroundColor,
        color: textDark,
        minHeight: '100vh',
        overflowY: 'auto',
        overflowX: 'hidden'
      }}
    >
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@300;400;500;600&family=Inter:wght@300;400;500&family=Outfit:wght@300;400;500;600&family=Syne:wght@400;500;600&display=swap');

        .bold-section {
          opacity: 0;
          transform: translateY(60px);
          transition: opacity 1s cubic-bezier(0.16, 1, 0.3, 1), transform 1s cubic-bezier(0.16, 1, 0.3, 1);
        }
        .bold-section.visible {
          opacity: 1;
          transform: translateY(0);
        }
        .service-row {
          border-bottom: 1px solid ${textDark}10;
          transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
        }
        .service-row:hover {
          padding-left: 20px;
          background: ${textDark}05;
        }
        .team-card {
          transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
        }
        .team-card:hover {
          transform: translateY(-8px);
        }
        .cta-btn {
          transition: all 0.4s ease;
          position: relative;
          overflow: hidden;
        }
        .cta-btn::before {
          content: '';
          position: absolute;
          top: 0;
          left: -100%;
          width: 100%;
          height: 100%;
          background: ${backgroundColor};
          transition: left 0.4s ease;
        }
        .cta-btn:hover::before {
          left: 0;
        }
        .cta-btn:hover {
          color: ${textDark};
        }
        .word-reveal {
          display: inline-block;
          overflow: hidden;
        }
        .word-reveal span {
          display: inline-block;
          transform: translateY(100%);
          animation: revealWord 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }
        @keyframes revealWord {
          to { transform: translateY(0); }
        }
      `}</style>

      {/* Hero Section */}
      <section 
        data-section="hero"
        className={`bold-section ${isVisible('hero') ? 'visible' : ''}`}
        style={{
          minHeight: '100vh',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          padding: '60px 8vw',
          position: 'relative'
        }}
      >
        <div style={{
          position: 'absolute',
          top: '60px',
          right: '8vw',
          fontSize: '13px',
          color: textMuted,
          letterSpacing: '0.05em'
        }}>
          Creative Studio
        </div>

        <h1 style={{
          fontFamily: headingFont,
          fontSize: `clamp(48px, 8vw, ${heroSize}px)`,
          fontWeight: 500,
          lineHeight: 1.0,
          letterSpacing: '-0.03em',
          maxWidth: '12ch',
          marginBottom: '60px'
        }}>
          {heroStatement.split(' ').map((word, i) => (
            <span key={i} className="word-reveal" style={{ marginRight: '0.3em' }}>
              <span style={{ animationDelay: `${i * 0.1}s` }}>{word}</span>
            </span>
          ))}
        </h1>

        <p style={{
          fontSize: 'clamp(18px, 2vw, 22px)',
          lineHeight: 1.6,
          color: textMuted,
          maxWidth: '540px',
          fontWeight: 300
        }}>{subStatement}</p>

        <div style={{
          position: 'absolute',
          bottom: '60px',
          left: '8vw',
          display: 'flex',
          gap: '80px'
        }}>
          {[
            { value: stat1Value, label: stat1Label },
            { value: stat2Value, label: stat2Label },
            { value: stat3Value, label: stat3Label }
          ].map((stat, i) => (
            <div key={i}>
              <p style={{
                fontFamily: headingFont,
                fontSize: '32px',
                fontWeight: 500,
                letterSpacing: '-0.02em'
              }}>{stat.value}</p>
              <p style={{
                fontSize: '12px',
                color: textMuted,
                textTransform: 'uppercase',
                letterSpacing: '0.1em',
                marginTop: '4px'
              }}>{stat.label}</p>
            </div>
          ))}
        </div>
      </section>

      {/* Belief Section */}
      <section
        data-section="belief"
        className={`bold-section ${isVisible('belief') ? 'visible' : ''}`}
        style={{
          padding: '200px 8vw',
          display: 'grid',
          gridTemplateColumns: '1fr 1fr',
          gap: '120px',
          alignItems: 'center'
        }}
      >
        <div>
          <p style={{
            fontSize: '12px',
            textTransform: 'uppercase',
            letterSpacing: '0.2em',
            color: textMuted,
            marginBottom: '30px'
          }}>{beliefTitle}</p>
        </div>
        <div>
          <p style={{
            fontFamily: headingFont,
            fontSize: 'clamp(28px, 3.5vw, 42px)',
            fontWeight: 400,
            lineHeight: 1.4,
            letterSpacing: '-0.02em'
          }}>{beliefText}</p>
        </div>
      </section>

      {/* Services Section */}
      <section
        data-section="services"
        className={`bold-section ${isVisible('services') ? 'visible' : ''}`}
        style={{
          padding: '100px 8vw 200px'
        }}
      >
        <p style={{
          fontSize: '12px',
          textTransform: 'uppercase',
          letterSpacing: '0.2em',
          color: textMuted,
          marginBottom: '60px'
        }}>What We Do</p>

        {services.map((service, i) => (
          <div 
            key={i}
            className="service-row"
            onMouseEnter={() => setHoveredService(i)}
            onMouseLeave={() => setHoveredService(null)}
            style={{
              display: 'grid',
              gridTemplateColumns: '80px 1fr 1fr',
              padding: '40px 0',
              alignItems: 'center',
              cursor: 'pointer'
            }}
          >
            <span style={{
              fontFamily: headingFont,
              fontSize: '14px',
              color: textMuted
            }}>{service.num}</span>
            <h3 style={{
              fontFamily: headingFont,
              fontSize: 'clamp(24px, 3vw, 36px)',
              fontWeight: 500,
              letterSpacing: '-0.02em',
              transform: hoveredService === i ? 'translateX(10px)' : 'translateX(0)',
              transition: 'transform 0.4s ease'
            }}>{service.title}</h3>
            <p style={{
              fontSize: '15px',
              color: textMuted,
              opacity: hoveredService === i ? 1 : 0.6,
              transition: 'opacity 0.4s ease'
            }}>{service.desc}</p>
          </div>
        ))}
      </section>

      {/* Team Section */}
      <section
        data-section="team"
        className={`bold-section ${isVisible('team') ? 'visible' : ''}`}
        style={{
          padding: '100px 8vw 200px',
          backgroundColor: `${textDark}05`
        }}
      >
        <p style={{
          fontSize: '12px',
          textTransform: 'uppercase',
          letterSpacing: '0.2em',
          color: textMuted,
          marginBottom: '80px'
        }}>The Team</p>

        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(3, 1fr)',
          gap: '40px 60px'
        }}>
          {team.map((member, i) => (
            <div key={i} className="team-card" style={{ cursor: 'pointer' }}>
              <div style={{
                aspectRatio: '1',
                backgroundColor: textDark,
                marginBottom: '24px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center'
              }}>
                <span style={{
                  fontFamily: headingFont,
                  fontSize: '48px',
                  color: backgroundColor,
                  fontWeight: 300
                }}>{member.name.split(' ').map(n => n[0]).join('')}</span>
              </div>
              <h4 style={{
                fontFamily: headingFont,
                fontSize: '20px',
                fontWeight: 500,
                marginBottom: '6px',
                letterSpacing: '-0.01em'
              }}>{member.name}</h4>
              <p style={{
                fontSize: '14px',
                color: textMuted
              }}>{member.role}</p>
            </div>
          ))}
        </div>
      </section>

      {/* Values Section */}
      <section
        data-section="values"
        className={`bold-section ${isVisible('values') ? 'visible' : ''}`}
        style={{
          padding: '200px 8vw'
        }}
      >
        <h2 style={{
          fontFamily: headingFont,
          fontSize: 'clamp(48px, 8vw, 120px)',
          fontWeight: 500,
          lineHeight: 0.95,
          letterSpacing: '-0.04em',
          textAlign: 'center',
          maxWidth: '10ch',
          margin: '0 auto'
        }}>
          Less noise.<br />More signal.
        </h2>
      </section>

      {/* CTA Section */}
      <section
        data-section="cta"
        className={`bold-section ${isVisible('cta') ? 'visible' : ''}`}
        style={{
          padding: '200px 8vw',
          backgroundColor: textDark,
          color: backgroundColor,
          textAlign: 'center'
        }}
      >
        <p style={{
          fontSize: '14px',
          textTransform: 'uppercase',
          letterSpacing: '0.2em',
          opacity: 0.6,
          marginBottom: '40px'
        }}>Ready to begin?</p>

        <h2 style={{
          fontFamily: headingFont,
          fontSize: 'clamp(36px, 5vw, 64px)',
          fontWeight: 500,
          letterSpacing: '-0.03em',
          marginBottom: '60px'
        }}>Let's create something<br />extraordinary together.</h2>

        <button 
          className="cta-btn"
          style={{
            fontFamily: headingFont,
            fontSize: '14px',
            letterSpacing: '0.1em',
            textTransform: 'uppercase',
            padding: '22px 56px',
            background: backgroundColor,
            color: textDark,
            border: 'none',
            cursor: 'pointer',
            position: 'relative',
            zIndex: 1
          }}
        >
          <span style={{ position: 'relative', zIndex: 2 }}>{ctaText}</span>
        </button>
      </section>

      <footer style={{
        padding: '40px 8vw',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        borderTop: `1px solid ${textDark}10`
      }}>
        <p style={{ fontSize: '13px', color: textMuted }}>
          © {new Date().getFullYear()} Studio. All rights reserved.
        </p>
        <div style={{ display: 'flex', gap: '30px' }}>
          {['Twitter', 'Instagram', 'LinkedIn'].map((social, i) => (
            <a key={i} href="#" style={{
              fontSize: '13px',
              color: textMuted,
              textDecoration: 'none',
              transition: 'color 0.3s ease'
            }}>{social}</a>
          ))}
        </div>
      </footer>
    </div>
  );
}

