                    zIndex: 1
                  }} 
                />
                <p style={{
                  fontSize: '20px',
                  fontWeight: 600,
                  marginBottom: '8px',
                  letterSpacing: '-0.01em'
                }}>{item.year}</p>
                <p style={{
                  fontSize: '14px',
                  color: textSecondary,
                  maxWidth: '140px',
                  margin: '0 auto'
                }}>{item.event}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Investors Section */}
      <section
        data-section="investors"
        className={`tech-section ${isVisible('investors') ? 'visible' : ''}`}
        style={{
          padding: '80px 60px',
          maxWidth: '1200px',
          margin: '0 auto',
          textAlign: 'center'
        }}
      >
        <p style={{
          fontSize: '12px',
          fontWeight: 600,
          textTransform: 'uppercase',
          letterSpacing: '0.1em',
          color: textSecondary,
          marginBottom: '40px'
        }}>Backed By</p>

        <div style={{
          display: 'flex',
          justifyContent: 'center',
          flexWrap: 'wrap',
          gap: '48px'
        }}>
          {investors.map((investor, i) => (
            <span 
              key={i}
              style={{
                fontSize: '18px',
                fontWeight: 500,
                color: textSecondary,
                opacity: 0.7
              }}
            >{investor}</span>
          ))}
        </div>
      </section>

      {/* CTA Section */}
      <section
        data-section="cta"
        className={`tech-section ${isVisible('cta') ? 'visible' : ''}`}
        style={{
          padding: '120px 60px',
          backgroundColor: textPrimary,
          color: cardBackground,
          textAlign: 'center'
        }}
      >
        <h2 style={{
          fontSize: 'clamp(28px, 4vw, 42px)',
          fontWeight: 600,
          letterSpacing: '-0.02em',
          marginBottom: '20px'
        }}>Join us in shaping the future</h2>

        <p style={{
          fontSize: '17px',
          opacity: 0.7,
          marginBottom: '40px',
          maxWidth: '500px',
          margin: '0 auto 40px'
        }}>We're always looking for exceptional talent to join our mission.</p>

        <button 
          className="cta-button"
          style={{
            fontFamily: headingFont,
            fontSize: '15px',
            fontWeight: 600,
            padding: '16px 40px',
            backgroundColor: accentColor,
            color: '#FFFFFF',
            border: 'none',
            borderRadius: '8px',
            cursor: 'pointer'
          }}
        >{ctaText}</button>
      </section>

      <footer style={{
        padding: '32px 60px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        borderTop: `1px solid ${borderColor}`
      }}>
        <p style={{ fontSize: '13px', color: textSecondary }}>
          © {new Date().getFullYear()} {companyName}. All rights reserved.
        </p>
        <div style={{ display: 'flex', gap: '24px' }}>
          {['Careers', 'Blog', 'Docs', 'Status'].map((link, i) => (
            <a key={i} href="#" style={{
              fontSize: '13px',
              color: textSecondary,
              textDecoration: 'none'
            }}>{link}</a>
          ))}
        </div>
      </footer>
    </div>
  );
}

