    { num: "02", title: "Obsessive Craft", desc: "Details aren't details—they're the design. We refine until perfection feels effortless." },
    { num: "03", title: "Fearless Innovation", desc: "Safe is the enemy of great. We take risks that redefine what's possible." },
    { num: "04", title: "Player First", desc: "Every decision, every pixel, every line of code serves the people who experience our work." }
  ];

  const leadership = [
    { name: "Viktor Kane", role: "Founder & CEO", desc: "Former Pixar, 20 years in immersive entertainment" },
    { name: "Elena Storm", role: "Chief Creative", desc: "Built worlds for Blizzard & Riot" },
    { name: "Marcus Reyes", role: "CTO", desc: "Ex-Google DeepMind, AI pioneer" }
  ];

  const timeline = [
    { year: "2012", title: "Genesis", desc: "Founded in a garage with 4 rebels" },
    { year: "2015", title: "First Hit", desc: "10 million players in 90 days" },
    { year: "2018", title: "Global Expansion", desc: "Studios in LA, London, Tokyo" },
    { year: "2021", title: "Next Frontier", desc: "AR/VR division launched" },
    { year: "2024", title: "Today", desc: "Defining the next decade" }
  ];

  React.useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const handleScroll = () => {
      const scrollTop = container.scrollTop;
      const scrollHeight = container.scrollHeight - container.clientHeight;
      setScrollProgress(scrollTop / scrollHeight);
    };

    container.addEventListener('scroll', handleScroll);
    return () => container.removeEventListener('scroll', handleScroll);
  }, []);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setVisibleSections(prev => new Set([...prev, entry.target.dataset.section]));
          }
        });
      },
      { threshold: 0.15, root: containerRef.current }
    );

    const sections = containerRef.current?.querySelectorAll('[data-section]');
    sections?.forEach(section => observer.observe(section));

    return () => observer.disconnect();
  }, []);

  const isVisible = (section) => visibleSections.has(section);

  return (
    <div 
      ref={containerRef}
