                  }}>{leader.desc}</p>
                </div>
              </div>
              <div style={{ padding: '24px 0' }}>
                <h4 style={{
                  fontFamily: "'Cinzel', serif",
                  fontSize: '22px',
                  fontWeight: 500,
                  marginBottom: '8px'
