          backgroundColor: 'transparent',
          color: textLight,
          border: `1px solid ${accentGold}`,
          cursor: 'pointer',
          transition: 'all 0.4s ease',
          position: 'relative',
          overflow: 'hidden'
        }}>{ctaText}</button>
      </section>

      <footer style={{
        padding: '60px 10vw',
        borderTop: `1px solid ${textMuted}20`,
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center'
      }}>
        <p style={{
          fontFamily: "'Cinzel', serif",
          fontSize: '14px',
          color: textMuted
        }}>© {new Date().getFullYear()} {companyName}</p>
        <div style={{ display: 'flex', gap: '40px' }}>
          {['Twitter', 'Instagram', 'LinkedIn', 'YouTube'].map((social, i) => (
            <a key={i} href="#" style={{
              fontSize: '13px',
              color: textMuted,
              textDecoration: 'none',
              textTransform: 'uppercase',
              letterSpacing: '0.1em',
              transition: 'color 0.3s ease'
            }}>{social}</a>
          ))}
        </div>
      </footer>
    </div>
  );
}

