function Component({ config = {} }) {
  const [visible, setVisible] = React.useState({});
  const refs = React.useRef({});

  const companyName = config?.companyName || "ארקייד גיימס";
  const heroTitle = config?.heroTitle || "מובילים את עולם הבידור";
  const heroSubtitle = config?.heroSubtitle || "מאז 2008";
  const introText = config?.introText || "חברת ארקייד גיימס נוסדה בשנת 2008...";
  const philosophyTitle = config?.philosophyTitle || "הפילוסופיה שלנו";
  const philosophyText = config?.philosophyText || "כחברה מובילה בתחומה...";
  const offerTitle = config?.offerTitle || "מה אנחנו מציעים";
  const offers = [
    config?.offer1 || "מכונות משחק ובובות",
    config?.offer2 || "מכונות ספורט ורכיבה",
    config?.offer3 || "משחקי סימולטור ומתקנים",
    config?.offer4 || "שירותי התקנה ותחזוקה",
    config?.offer5 || "ייעוץ והדרכה מקצועיים",
    config?.offer6 || "ליווי עסקי מלא"
  ];
  const clientsText = config?.clientsText || "לחברה מוניטין גבוה בענף...";
  const ctaTitle = config?.ctaTitle || "מוכנים להתחיל?";
  const ctaButton = config?.ctaButton || "דברו איתנו";

  const leftBackground = config?.leftBackground || "#18181B";
  const rightBackground = config?.rightBackground || "#FAFAFA";
  const lightText = config?.lightText || "#FFFFFF";
  const darkText = config?.darkText || "#18181B";
  const mutedLight = config?.mutedLight || "#A1A1AA";
  const mutedDark = config?.mutedDark || "#71717A";

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setVisible(prev => ({ ...prev, [entry.target.id]: true }));
          }
        });
      },
      { threshold: 0.15 }
    );

    Object.values(refs.current).forEach(ref => {
      if (ref) observer.observe(ref);
    });

    return () => observer.disconnect();
  }, []);

  return (
    <div className="about-split" style={{
      fontFamily: '"Noto Sans Hebrew", "Noto Sans", sans-serif',
      minHeight: '100vh',
      direction: 'rtl'
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+Hebrew:wght@300;400;500&display=swap');

        @keyframes slideRight {
          from { opacity: 0; transform: translateX(-40px); }
          to { opacity: 1; transform: translateX(0); }
        }

        @keyframes slideLeft {
          from { opacity: 0; transform: translateX(40px); }
          to { opacity: 1; transform: translateX(0); }
        }

        .split-left {
          animation: slideRight 0.8s cubic-bezier(0.22, 1, 0.36, 1) forwards;
          opacity: 0;
        }

        .split-right {
          animation: slideLeft 0.8s cubic-bezier(0.22, 1, 0.36, 1) forwards;
          opacity: 0;
        }
      `}</style>

      {/* Hero Section */}
      <section 
        id="hero"
        ref={el => refs.current.hero = el}
        style={{
          display: 'grid',
          gridTemplateColumns: '1fr 1fr',
          minHeight: '100vh'
        }}
      >
        {/* Right - Dark */}
        <div style={{
          backgroundColor: leftBackground,
          color: lightText,
          padding: '80px',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'space-between'
        }}>
          <span className={visible.hero ? 'split-left' : ''} style={{
            fontSize: '14px',
            fontWeight: 500,
            letterSpacing: '0.1em',
            color: mutedLight
          }}>
            {companyName}
          </span>
          <div>
            <h1 className={visible.hero ? 'split-left' : ''} style={{
              fontSize: 'clamp(36px, 5vw, 64px)',
              fontWeight: 300,
              lineHeight: 1.1,
              marginBottom: '24px',
              animationDelay: '0.1s'
            }}>
              {heroTitle}
            </h1>
            <p className={visible.hero ? 'split-left' : ''} style={{
              fontSize: '20px',
              fontWeight: 400,
              color: mutedLight,
              animationDelay: '0.2s'
            }}>
              {heroSubtitle}
            </p>
          </div>
          <div style={{ height: '60px' }} />
        </div>

        {/* Left - Light */}
        <div style={{
          backgroundColor: rightBackground,
          color: darkText,
          padding: '80px',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center'
        }}>
          <p className={visible.hero ? 'split-right' : ''} style={{
            fontSize: 'clamp(18px, 2vw, 22px)',
            fontWeight: 400,
            lineHeight: 1.7,
            maxWidth: '500px',
            animationDelay: '0.2s'
          }}>
            {introText}
          </p>
        </div>
      </section>

      {/* Philosophy Section */}
      <section 
        id="philosophy"
        ref={el => refs.current.philosophy = el}
        style={{
          display: 'grid',
          gridTemplateColumns: '1fr 1fr',
          minHeight: '60vh'
        }}
      >
        <div style={{
          backgroundColor: rightBackground,
          color: darkText,
          padding: '80px',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center'
        }}>
          <h2 className={visible.philosophy ? 'split-left' : ''} style={{
            fontSize: '14px',
            fontWeight: 500,
            letterSpacing: '0.1em',
            color: mutedDark,
            marginBottom: '30px'
          }}>
            {philosophyTitle}
          </h2>
          <p className={visible.philosophy ? 'split-left' : ''} style={{
            fontSize: 'clamp(20px, 2.5vw, 28px)',
            fontWeight: 400,
            lineHeight: 1.6,
            animationDelay: '0.1s'
          }}>
            {philosophyText}
          </p>
        </div>

        <div style={{
          backgroundColor: leftBackground,
          color: lightText,
          padding: '80px',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center'
        }}>
          <h2 className={visible.philosophy ? 'split-right' : ''} style={{
            fontSize: '14px',
            fontWeight: 500,
            letterSpacing: '0.1em',
            color: mutedLight,
            marginBottom: '40px'
          }}>
            {offerTitle}
          </h2>
          <div style={{
            display: 'grid',
            gridTemplateColumns: '1fr 1fr',
            gap: '24px'
          }}>
            {offers.map((offer, index) => (
              <p 
                key={index}
                className={visible.philosophy ? 'split-right' : ''}
                style={{
                  fontSize: '16px',
                  fontWeight: 400,
                  animationDelay: `${0.15 + index * 0.05}s`,
                  display: 'flex',
                  alignItems: 'center',
                  gap: '12px'
                }}
              >
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
                  <path d="M5 12h14M12 5l7 7-7 7" />
                </svg>
                {offer}
              </p>
            ))}
          </div>
        </div>
      </section>

      {/* Clients Section */}
      <section 
        id="clients"
        ref={el => refs.current.clients = el}
        style={{
          backgroundColor: rightBackground,
          padding: '120px 80px',
          textAlign: 'center'
        }}
      >
        <div style={{ maxWidth: '800px', margin: '0 auto' }}>
          <p className={visible.clients ? 'split-left' : ''} style={{
            fontSize: 'clamp(20px, 2.5vw, 28px)',
            fontWeight: 400,
            lineHeight: 1.7,
            color: darkText
          }}>
            {clientsText}
          </p>
        </div>
      </section>

      {/* CTA Section */}
      <section 
        id="cta"
        ref={el => refs.current.cta = el}
        style={{
          display: 'grid',
          gridTemplateColumns: '1fr 1fr',
          minHeight: '50vh'
        }}
      >
        <div style={{
          backgroundColor: leftBackground,
          color: lightText,
          padding: '80px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center'
        }}>
          <h2 className={visible.cta ? 'split-left' : ''} style={{
            fontSize: 'clamp(32px, 4vw, 52px)',
            fontWeight: 300,
            textAlign: 'center'
          }}>
            {ctaTitle}
          </h2>
        </div>

        <div style={{
          backgroundColor: rightBackground,
          color: darkText,
          padding: '80px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center'
        }}>
          <button
            className={visible.cta ? 'split-right' : ''}
            style={{
              backgroundColor: leftBackground,
              color: lightText,
              border: 'none',
              padding: '20px 60px',
              fontSize: '16px',
              fontWeight: 500,
              cursor: 'pointer',
              transition: 'transform 0.3s ease, opacity 0.3s ease'
            }}
            onMouseEnter={e => {
              e.target.style.transform = 'translateY(-3px)';
              e.target.style.opacity = '0.9';
            }}
            onMouseLeave={e => {
              e.target.style.transform = 'translateY(0)';
              e.target.style.opacity = '1';
            }}
          >
            {ctaButton}
          </button>
        </div>
      </section>
    </div>
  );
}

