    hero: {
      minHeight: '100vh',
      backgroundColor: darkBackground,
      color: lightText,
      display: 'flex',
      flexDirection: 'column',
      justifyContent: 'center',
      alignItems: 'center',
      position: 'relative',
      padding: '80px 48px'
    },
    heroContent: {
      textAlign: 'center',
      maxWidth: '1200px'
    },
    heroLines: {
      marginBottom: '48px'
