    heroLine: (index) => ({
      display: 'block',
      fontSize: 'clamp(56px, 14vw, 180px)',
      fontWeight: '300',
      lineHeight: '0.95',
      letterSpacing: '-0.03em',
      opacity: isVisible(0) ? 1 : 0,
      transform: isVisible(0) ? 'translateY(0) rotate(0)' : `translateY(80px) rotate(${index === 1 ? 3 : -3}deg)`,
      transition: `all 1s cubic-bezier(0.22, 1, 0.36, 1) ${index * 0.12}s`
    }),
    heroLineOutline: {
      WebkitTextStroke: `1.5px ${lightText}`,
      WebkitTextFillColor: 'transparent'
    },
    heroTagline: {
      fontSize: 'clamp(16px, 2vw, 20px)',
      fontWeight: '400',
      color: mutedText,
      letterSpacing: '0.02em',
      opacity: isVisible(0) ? 1 : 0,
      transform: isVisible(0) ? 'translateY(0)' : 'translateY(30px)',
      transition: 'all 0.8s cubic-bezier(0.22, 1, 0.36, 1) 0.5s'
