      color: lightText,
      border: 'none',
      borderRadius: '100px',
      fontSize: '16px',
      fontWeight: '500',
      cursor: 'pointer',
      transition: 'all 0.4s ease',
      opacity: isVisible(6) ? 1 : 0,
      transform: isVisible(6) ? 'translateY(0)' : 'translateY(30px)',
      transitionDelay: '0.25s'
    },
    footer: {
      padding: '48px 80px',
      backgroundColor: darkBackground,
      color: lightText,
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center'
    },
    footerLogo: {
      fontSize: '16px',
      fontWeight: '500'
    },
    footerCopy: {
      fontSize: '14px',
      color: mutedText
    }
  };

  return (
    <div style={styles.page} className="about-immersive">
      <link href="https://fonts.googleapis.com/css2?family=Noto+Sans+Hebrew:wght@300;400;500&display=swap" rel="stylesheet" />

      {/* Hero Section */}
      <section style={styles.hero} ref={setSectionRef(0)}>
        <div style={styles.heroContent}>
          <div style={styles.heroLines}>
            <span style={styles.heroLine(0)}>{heroLine1}</span>
            <span style={{...styles.heroLine(1), ...styles.heroLineOutline}}>{heroLine2}</span>
            <span style={styles.heroLine(2)}>{heroLine3}</span>
          </div>
          <p style={styles.heroTagline}>{heroTagline}</p>
        </div>
        <div style={styles.scrollIndicator}>
          <span>גלול למטה</span>
          <ChevronIcon direction="down" />
        </div>
      </section>

      {/* Story Section */}
      <section style={styles.storySection} ref={setSectionRef(1)}>
        <div style={styles.storyLeft}>
          <div style={styles.sectionNumber}>01</div>
          <div style={styles.sectionTitle}>{storyTitle}</div>
          <h2 style={styles.storyHeadline}>מומחים לעולם הבידור והמשחק</h2>
          <p style={styles.storyParagraph}>{storyText}</p>
